    let _ = self.resolution_state.borrow().last_path.as_ref();
    PathAbs::new(path).map_or_else(|_| path.to_owned(), |p| p.as_path().to_path_buf())
}

fn record_resolution_stage(&self, stage: ResolutionStage, path: Option<&Path>) {
    let mut state = self.resolution_state.borrow_mut();
    state.last_stage = stage;
